const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, m => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[m]));
}

function toast(t) {
  $('#toast').textContent = t;
  $('#toast').classList.remove('hidden');
  setTimeout(() => $('#toast').classList.add('hidden'), 2400);
}

// LIVE diagnostics: concise toast for the user and full details in DevTools.
function showLiveNotificationDiagnostic(title, lines = [], persist = true) {
  try {
    if (Array.isArray(lines) && lines.length) {
      console.groupCollapsed(`[GRAYXON LIVE] ${title || 'Diagnóstico'}`);
      lines.forEach(line => console.log(line));
      console.groupEnd();
    }
    if (persist !== false && title) toast(title);
  } catch (e) {
    console.warn('[GRAYXON LIVE] No se pudo mostrar el diagnóstico:', e);
  }
}

function errorText(error, fallbackText = 'Ocurrió un error.') {
  return error?.message || fallbackText;
}

function restoreLiveNotificationDiagnostic() {
  try {
    const raw = sessionStorage.getItem('grayxon_live_diag');
    if (!raw) return;
    const diag = JSON.parse(raw);
    if (!diag?.title || !Array.isArray(diag.lines)) return;
    sessionStorage.removeItem('grayxon_live_diag');
    showLiveNotificationDiagnostic(diag.title, diag.lines, false);
  } catch (_) {}
}

async function loadNotifications() {
  if (!session?.user?.id) { notifications = []; updateNotificationsUI(); return; }
  // Mostrar todo lo de los últimos 7 días y conservar también pendientes más antiguas.
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
  const { data, error } = await sb.from('notifications')
    .select('id,type,title,message,link_page,link_target,related_week_start,related_week_end,read_at,created_at')
    .eq('user_id', session.user.id)
    .or(`created_at.gte.${sevenDaysAgo},read_at.is.null`)
    .order('created_at', { ascending: false });
  if (error) { notifications = []; updateNotificationsUI(); return; }
  notifications = data || [];
  updateNotificationsUI();
}

