  const concepts=its.length?its.map(i=>`<article class="gx-payment-concept"><div class="gx-payment-concept-copy"><strong>${esc(i.concept)}</strong><small>${i.currency==='USD'?`${gxPaymentMoney(i.amount_original,'USD')} × TRM ${gxPaymentMoney(i.trm)}`:gxPaymentMoney(i.amount_cop)}</small></div><b>${gxPaymentMoney(i.amount_cop)}</b></article>`).join(''):`<article class="gx-payment-concept"><div class="gx-payment-concept-copy"><strong>${esc(p.concept||'Concepto de pago')}</strong></div><b>${gxPaymentMoney(p.amount)}</b></article>`;
  const overlay=document.createElement('section');overlay.id='gx-payment-detail-fullscreen';overlay.className='gx-payment-fullscreen gx-payment-detail-fullscreen';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Detalle completo del pago');
  overlay.innerHTML=`<header class="gx-payment-fullscreen-header"><button type="button" class="gx-payment-back" data-gx-detail-close>← Volver a mis pagos</button><div class="gx-payment-brand"><span class="gx-payment-brand-mark">G</span><span><b>GRAYXON</b><small>Comprobante de pago</small></span></div><span class="pill ${stateClass}">${status}</span></header><main class="gx-payment-fullscreen-main"><div class="gx-payment-receipt-heading"><div><div class="eyebrow">LIQUIDACIÓN DE PAGO</div><h1>Comprobante de pago</h1><p>Ref. ${esc(p.id.slice(0,8).toUpperCase())}</p></div><span class="gx-payment-verified">${p.status==='paid'?'✓ Pago confirmado':'Estado del pago'}</span></div><section class="gx-payment-detail-section"><h2>Información general</h2><div class="gx-payment-info-grid"><div><span>Beneficiario</span><strong>${esc(label)}</strong></div><div><span>Fecha de pago</span><strong>${gxPaymentDate(p.payment_date)}</strong></div><div><span>Método de pago</span><strong>${esc(acc.method)}</strong></div><div class="gx-payment-account-line"><span>Cuenta seleccionada</span><strong>${esc(acc.account)}</strong>${acc.detail?`<small>${esc(acc.detail)}</small>`:''}</div><div><span>Referencia de transferencia</span><strong>${esc(p.reference||'—')}</strong></div></div></section><section class="gx-payment-detail-section"><h2>Resumen de métricas</h2><div class="gx-payment-metric-grid">${metricData.map(m=>`<article class="gx-payment-metric"><span class="gx-payment-metric-icon">${m.icon}</span><span class="gx-payment-metric-label">${esc(m.label)}</span><strong>${esc(m.value)}</strong></article>`).join('')}</div></section><section class="gx-payment-detail-section"><h2>Conceptos de pago</h2><div class="gx-payment-concepts">${concepts}</div>${p.amount_usd!=null?`<div class="gx-payment-subtotal"><span>Total original en USD</span><strong>${gxPaymentMoney(p.amount_usd,'USD')}</strong></div>`:''}${p.trm!=null?`<div class="gx-payment-subtotal"><span>TRM global de referencia</span><strong>${gxPaymentMoney(p.trm)}</strong></div>`:''}</section>${p.notes?`<section class="gx-payment-detail-section"><h2>Notas</h2><p class="gx-payment-notes-text">${esc(p.notes)}</p></section>`:''}<section class="gx-payment-total-card"><span>TOTAL ${p.status==='paid'?'PAGADO':'REGISTRADO'}</span><strong>${gxPaymentMoney(p.amount)}</strong><small>COP · Pesos colombianos</small></section>${p.receipt_path?`<button type="button" class="gx-payment-receipt-button gx-payment-fullscreen-receipt-button" data-gx-detail-receipt>📄 Ver comprobante adjunto</button>`:'<div class="gx-payment-no-receipt">Este pago no tiene un archivo de comprobante adjunto.</div>'}${isAdmin?`<div class="gx-payment-detail-admin"><button type="button" class="secondary" data-gx-detail-edit>Editar pago</button>${p.status==='pending'?'<button type="button" class="primary" data-gx-detail-paid>Marcar como pagado y notificar</button>':''}<button type="button" class="secondary danger" data-gx-detail-delete>Eliminar pago</button></div>`:''}</main>`;
