function ensureCreatorSpaceFloat(){
  // El botón flotante «Mi espacio» fue retirado del portal.
  // También elimina cualquier instancia que haya quedado viva en una sesión ya abierta.
  document.getElementById('grayxonCreatorSpaceFloat')?.remove();
  return null;
}

function updateCreatorSpaceFloat(){
  document.getElementById('grayxonCreatorSpaceFloat')?.remove();
  const creatorSession=!!session && (profile?.role==='creator' || document.body.classList.contains('grayxon-creator-session'));
  document.body.classList.toggle('grayxon-creator-session',creatorSession);
}

function updateCreatorTopNav(){
  const role=profile?.role||'';
  const isAdmin=!!session&&role==='admin';
  const isCreator=!!session&&(role==='creator'||document.body.classList.contains('grayxon-creator-session'));
  const benefitsButton=Array.from(document.querySelectorAll('[data-page="benefits"]'));
  benefitsButton.forEach(b=>{b.textContent=isAdmin?'Inicio':'Beneficios y requisitos';b.dataset.page=isAdmin?'home':'benefits';b.classList.remove('hidden');b.style.setProperty('display','', 'important');b.setAttribute('aria-label',isAdmin?'Ir al sitio público de Grayxon':'Ver beneficios y requisitos');});
  const spaceButtons=Array.from(document.querySelectorAll('[data-page="space"]'));
  spaceButtons.forEach(b=>{
    b.textContent=isAdmin?'Admin':'Tu espacio';
    b.dataset.page=isAdmin?'admin':'space';
    const hide=isCreator;
    b.classList.toggle('hidden',hide);
    b.style.setProperty('display',hide?'none':'', 'important');
    b.setAttribute('aria-hidden',hide?'true':'false');
    b.setAttribute('aria-label',isAdmin?'Abrir panel de administración':'Abrir tu espacio');
  });
  // El botón original "Inicio" se oculta solo para administración: su acceso "Inicio" es el que antes era "Beneficios y requisitos".
  const publicHomeButton=document.querySelector('.nav button[data-page="home"]');
  if(publicHomeButton){const hideOriginalHome=isAdmin;publicHomeButton.classList.toggle('hidden',hideOriginalHome);publicHomeButton.style.setProperty('display',hideOriginalHome?'none':'','important');publicHomeButton.setAttribute('aria-hidden',hideOriginalHome?'true':'false');}
  const adminButton=$('#adminOpen');
  if(adminButton){adminButton.classList.add('hidden');adminButton.style.setProperty('display','none','important');adminButton.setAttribute('aria-hidden','true');}
}

function isCreatorSession(){
  return !!session && (profile?.role === 'creator' || document.body.classList.contains('grayxon-creator-session'));
}

function nav(p, push = true) {
  const thisNav = ++navGeneration;
  const pages = ['home','benefits','auth','space','manager','training','live-training','missions','profile','admin','announcements','payments','events','force-password'];
  if (!pages.includes(p)) p = 'home';
  if (p === 'events' && typeof ensureEventsPage === 'function') ensureEventsPage();
  if (p === 'force-password' && !session) p = 'auth';
  if (session && profile?.must_change_password && p !== 'force-password') p = 'force-password';
  // Sin sesión, Inicio debe volver a la portada pública nueva y no mostrar la portada antigua del portal.
  if (!session && p === 'home') {
    window.location.replace('./index.html?v=20261019');
    return;
  }
  if (session && p === 'space' && profile?.role === 'manager') p = 'manager';
  if (p === 'manager') managerView = 'dashboard';
  if (p === 'live-training') ensureLiveTrainingPage();
  if (p === 'payments') { ensurePaymentsPage(); if(!session) p='auth'; }
  if (p === 'events' && !session) p = 'auth';
  // Para creadores, Mi espacio debe volver a pintar inmediatamente el dashboard real.
  // Evita pasar primero por el shell antiguo con estados de carga al volver desde
  // Misiones, Mi perfil o Formación.
  // El dashboard inmediato se pinta una sola vez desde spaceTpl(). Evitamos
  // reconstruirlo aquí y volver a reemplazarlo al entrar en el template.
  if (p === 'live-training') { const se=$('#space'); if(se){se.hidden=true;se.classList.add('hidden');se.style.setProperty('display','none','important');} document.body.classList.add('grayxon-live-training-active'); }
  if (push && current !== p) {
    const url = p === 'home'
      ? `${window.location.pathname}${window.location.search}`
      : `${window.location.pathname}${window.location.search}#${p}`;
    history.pushState({page:p}, '', url);
  }
  current = p;
  document.body.classList.toggle('grayxon-auth-active', p === 'auth');
  document.documentElement.classList.toggle('grayxon-auth-active', p === 'auth');
  if(p==='space' && isCreatorSession()) startCreatorLiveDashboardWatcher(); else stopCreatorLiveDashboardWatcher();
  updateCreatorSpaceFloat();
  updateCreatorTopNav();

  // Estado global de la sección de entrenamientos.
  document.body.classList.toggle('grayxon-live-training-active', p === 'live-training');

  // Hide every portal page robustly.
  pages.forEach(id => {
    const el = $('#'+id);
    if (!el) return;
    const isActive = id === p;
    el.classList.toggle('hidden', !isActive);
    el.hidden = !isActive;
    if (isActive) el.removeAttribute('aria-hidden');
    else el.setAttribute('aria-hidden','true');
  });

  // Mi espacio debe desaparecer COMPLETAMENTE mientras estamos en Entrenamientos,
  // incluso si alguna regla móvil intenta mostrar .page-section.
  const spaceEl = $('#space');
  if (spaceEl) {
    if (p === 'live-training') {
      spaceEl.hidden = true;
      spaceEl.setAttribute('aria-hidden','true');
      spaceEl.classList.add('hidden');
      spaceEl.style.setProperty('display', 'none', 'important');
    } else if (p === 'space') {
      spaceEl.hidden = false;
      spaceEl.removeAttribute('aria-hidden');
      spaceEl.classList.remove('hidden');
      spaceEl.style.removeProperty('display');
    }
  }

  if (p !== 'live-training' && jaasApi) destroyJaasMeeting();
  // El render de la página activa lo controla render(). Para creadores no
  // pintamos el shell antiguo aquí porque provocaba el estado "Cargando mi espacio..."
  // al volver desde Misiones/Mi perfil.
  // Para creadores, Mi espacio ya fue pintado de inmediato. No dejamos que un render
  // asíncrono antiguo vuelva a pisarlo mientras el usuario navega.
  if (p === 'space' && isCreatorSession()) {
    // Nunca bloqueamos la navegación esperando datos remotos. El dashboard ya está visible;
    // la actualización se ejecuta en segundo plano y solo pinta si seguimos en Mi espacio.
    creatorDashboardTpl(thisNav).then(()=>refreshMyPendingPaymentsBadge()).catch(e => console.warn('Creator dashboard:', e));
  } else {
    Promise.resolve(render()).then(()=>refreshMyPendingPaymentsBadge()).catch(e => console.warn('Render:', e));
  }
  window.scrollTo(0,0);
  if(typeof window.refreshGrayxonBottomActive==='function') setTimeout(window.refreshGrayxonBottomActive,0);
}

window.grayxonNavigateToDashboard = function(){
  if(!session){ nav('auth'); return; }
  const destination = profile?.role === 'admin' ? 'admin' : profile?.role === 'manager' ? 'manager' : 'space';
  window.grayxonDashboardPage = destination;
  /* Restablecer el subapartado interno antes de renderizar el panel principal. */
  if(destination === 'admin') adminView = 'dashboard';
  if(destination === 'manager') managerView = 'dashboard';
  nav(destination);
};
window.grayxonToggleProfileMenu = function(){
  if(!session){ nav('auth'); return; }
  toggleProfileMenu();
};
window.grayxonToggleNotifications = function(){
  if(!session){ nav('auth'); return; }
  toggleNotifications();
};

function spaceCard(icon,title,desc,pct,action,detail){
  if(!document.getElementById('gx-space-icon-normalization')){const style=document.createElement('style');style.id='gx-space-icon-normalization';style.textContent='.space-card{display:flex;align-items:center;gap:14px;min-width:0}.space-card-icon{width:48px!important;height:48px!important;min-width:48px!important;max-width:48px!important;flex:0 0 48px!important;display:flex!important;align-items:center!important;justify-content:center!important;box-sizing:border-box!important;line-height:1!important;overflow:hidden}.space-card-icon svg,.space-card-icon img,.space-card-icon i{width:24px!important;height:24px!important;max-width:24px!important;max-height:24px!important;flex:0 0 24px!important;object-fit:contain!important;font-size:24px!important;line-height:1!important}.space-card-main{flex:1 1 auto;min-width:0}.space-card-arrow{flex:0 0 20px;text-align:center}@media(max-width:650px){.space-card{gap:10px;padding:14px!important}.space-card-icon{width:44px!important;height:44px!important;min-width:44px!important;max-width:44px!important;flex-basis:44px!important}.space-card-icon svg,.space-card-icon img,.space-card-icon i{width:22px!important;height:22px!important;max-width:22px!important;max-height:22px!important;flex-basis:22px!important}.space-card-main p,.space-card-main small{overflow-wrap:anywhere}}';document.head.appendChild(style);}
  return `<button class="space-card card ${action==='payments'?'gx-payments-dashboard-card':''}" data-space-action="${esc(action)}"><span class="space-card-icon">${icon}</span><div class="space-card-main"><div class="space-card-top"><strong>${esc(title)}</strong><span>${pct}%</span></div><p>${esc(desc)}</p><div class="space-progress"><span style="width:${Math.max(0,Math.min(100,pct))}%"></span></div><small>${esc(detail)}</small></div><span class="space-card-arrow">›</span></button>`;
}
function renderSpaceShell(){
  const el=$('#space'); if(!el) return;
  if(!session){ el.innerHTML=authTpl(); return; }
  const base=profile||{full_name:session.user.user_metadata?.full_name||'',username:session.user.user_metadata?.username||session.user.email?.split('@')[0]||'creador'};
  el.innerHTML=`<div class="space-page"><div class="space-hero"><div class="space-hero-main"><div class="eyebrow">MI ESPACIO</div><h1>Hola, ${esc(base.username||'creador')} 👋</h1><p class="muted space-intro">Aquí tienes todo lo que necesitas para avanzar dentro de Grayxon.</p></div><div class="space-total"><span>PROGRESO GENERAL</span><strong id="spaceOverallPct">0%</strong></div><div id="spaceTeamBlock" class="space-team-inline"><div class="space-team-card space-team-card-loading"><div class="space-team-card-info"><span class="space-team-label">TU EQUIPO</span><strong>Cargando equipo...</strong></div></div></div></div><div class="space-grid" id="spaceCards">${spaceCard('👤','Tu perfil','Completa tus datos para mantener tu información actualizada.',0,'profile','Cargando información…')}${spaceCard('🎓','Formación','Aprende con los módulos, lecciones, videos y recursos de Grayxon.',0,'training','Cargando formación…')}${spaceCard('🎯','Tus misiones','Cumple tus objetivos semanales y registra tus avances.',0,'missions','Cargando misiones…')}${spaceCard('📣','Centro de comunicados','Consulta novedades, avisos importantes y recursos de tu equipo.',0,'announcements','Ver comunicados recientes')}${spaceCard('💸','Mis pagos','Consulta los pagos registrados a tu nombre y su historial.',0,'payments','Ver historial de pagos')}<button class="space-card card live-training-space-card" data-space-action="live-training"><span class="space-card-icon">🎥</span><div class="space-card-main"><div class="space-card-top"><strong>Entrenamientos</strong><span class="live-training-card-status">Sin entrenamiento</span></div><p class="live-training-card-title">Consulta los entrenamientos en vivo de Grayxon.</p><div class="space-progress"><span style="width:0%"></span></div><small class="live-training-card-detail">Cuando haya uno activo aparecerá aquí.</small></div><span class="space-card-arrow">›</span></button></div></div>`;
  bind();
  refreshLiveTrainingCard();
}
function updateSpaceTeam(a){
  const el=$('#spaceTeamBlock'); if(!el)return;
  if(a?.team){
    const m=a.manager;
    const contact = m?.phone
      ? `<a class="space-team-contact" href="${esc(managerWhatsapp(m.phone))}" target="_blank" rel="noopener noreferrer"><img src="assets/whatsapp-icon.svg" alt=""><span>Contactar</span><span class="space-team-contact-arrow">↗</span></a>`
      : '';
    el.innerHTML=`<div class="space-team-card"><div class="space-team-card-info"><span class="space-team-label">TU EQUIPO</span><strong>${esc(a.team.name)}</strong><span>Manager: <b>${esc(m?.name||'Sin manager asignado')}</b></span></div>${contact}</div>`;
  } else {
    el.innerHTML=`<div class="space-team-card space-team-card-empty"><span>Tu equipo: aún no tienes equipo asignado</span></div>`;
  }
}
function updateSpaceCard(action,pct,detail){const b=document.querySelector(`[data-space-action="${action}"]`);if(!b)return;const p=b.querySelector('.space-card-top span'),bar=b.querySelector('.space-progress span'),d=b.querySelector('small');if(p)p.textContent=`${pct}%`;if(bar)bar.style.width=`${Math.max(0,Math.min(100,pct))}%`;if(d)d.textContent=detail;}

async function render(){
  if(current==='home'||current==='benefits'||current==='admin'){
    const c=await content();
    if(current==='home')$('#home').innerHTML=homeTpl(c.home);
    if(current==='benefits')$('#benefits').innerHTML=benefitsTpl(c.benefits);
    if(current==='admin')await adminTpl(c);
  }
  if(current==='announcements') await announcementsTpl();
  if(current==='payments') { ensureGrayxonPaymentStyles(); await gxPaymentsPage(); }
  if (current==='events') await gxEventsPage();
  if(current==='auth')$('#auth').innerHTML=authTpl();
  if(current==='force-password')$('#force-password').innerHTML=forcePasswordTpl();
  if(current==='space') { if(profile?.role==='manager') await managerTpl(); else await spaceTpl(); }
  if(current==='manager')await managerTpl();
  if(current==='training')await trainingTpl();
  if(current==='live-training')await liveTrainingTpl();
  if(current==='missions')await missionsTpl();
  if(current==='profile'){ $('#profile').innerHTML=await profileTpl(); if(profile?.role==='creator') loadCreatorProfileManager(); }
  bind(); updateHeaderAccessUI(); if(current==='profile') ensureCreatorNotificationMenuAction(); updateProfileBadge(); updateNotificationsUI(); updateCreatorSpaceFloat(); updateCreatorTopNav();
  if(session && ['space','manager','admin'].includes(current)) gxRefreshAnnouncementUnreadCount();
  $$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===current || (b.dataset.page==='space' && current==='manager')));
}

