async function handleGrayxonDeepLinkUrl(urlValue) {
  try {
    const parsed = new URL(String(urlValue || ''), window.location.href);
    const hashRoute = parsed.hash.replace(/^#/, '');
    const queryPage = parsed.searchParams.get('page') || '';
    const page = hashRoute.startsWith('live-training/') ? hashRoute : (queryPage || hashRoute || 'home');
    if(session&&(page==='event-post'||parsed.searchParams.get('page')==='event-post')){const postId=parsed.searchParams.get('target')||'';return await gxEventsNavigateToPost(postId);}
    if (session && (page === 'event-match' || parsed.searchParams.get('page') === 'event-match')) {
      const matchId = parsed.searchParams.get('target') || '';
      if (!GRAYXON_UUID_RE.test(matchId)) return false;
      const {data: match,error} = await sb.from('gx_event_matches').select('event_id').eq('id',matchId).maybeSingle();
      if (error || !match?.event_id) { toast('Esta batalla ya no está disponible o no tienes acceso.'); return false; }
      gxPendingEventTarget = match.event_id;
      gxPendingEventMatchTarget = matchId;
      gxEventsActiveTab = 'missions';
      const desiredHash = '#events';
      if (window.location.hash !== desiredHash) window.history.replaceState({page:'events'}, '', `${window.location.pathname}${window.location.search}${desiredHash}`);
      if (current !== 'events') nav('events', false); else await gxEventsPage();
      return true;
    }
    if (session && (page === 'missions' || parsed.searchParams.get('page') === 'missions' || parsed.searchParams.get('page') === 'mission')) {
      const target = parsed.searchParams.get('target') || '';
      pendingNotificationTarget = { type:'missions', missionId:GRAYXON_UUID_RE.test(target)?target:null, weekStart:null, weekEnd:null };
      nav('missions', false);
      return true;
    }
    if (session && (page === 'events' || parsed.searchParams.get('page') === 'events')) {
      const target = parsed.searchParams.get('target') || '';
      gxPendingEventTarget = GRAYXON_UUID_RE.test(target) ? target : null;
      const desiredHash = '#events';
      if (window.location.hash !== desiredHash) {
        window.history.replaceState({page:'events'}, '', `${window.location.pathname}${window.location.search}${desiredHash}`);
      }
      if (current !== 'events') nav('events', false); else await gxEventsPage();
      return true;
    }
    if (session && (page === 'payments' || parsed.searchParams.get('page') === 'payments')) {
      const target = parsed.searchParams.get('target') || '';
      gxPendingPaymentTarget = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(target) ? target : null;
      const desiredHash = '#payments';
      if (window.location.hash !== desiredHash) {
        window.history.replaceState({page:'payments'}, '', `${window.location.pathname}${window.location.search}${desiredHash}`);
      }
      if (current !== 'payments') nav('payments', false); else await gxPaymentsPage();
      return true;
    }
    const deepLiveMatch = page.match(/^live-training\/([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i);
    if (!(session && deepLiveMatch)) return false;

    const liveId = deepLiveMatch[1];
    const { data: targetLive } = await sb.from('live_trainings')
      .select('id,title,description,scheduled_at,room_name,status,created_by,instructor_name,created_at,started_at,ended_at')
      .eq('id', liveId)
      .eq('status', 'live')
      .maybeSingle();

    if (!targetLive) {
      toast('Este LIVE ya no está disponible o no tienes acceso.');
      return false;
    }
    currentLiveTraining = targetLive;
    pendingLiveTrainingAutoStart = { id: targetLive.id };
    if (window.location.hash !== `#live-training/${targetLive.id}`) {
      window.history.replaceState({ page: 'live-training' }, '', `${window.location.pathname}${window.location.search}#live-training/${targetLive.id}`);
    }
    if (current !== 'live-training') {
      current = 'live-training';
      render();
    } else {
      ensureLiveTrainingPage();
    }
    updateCreatorSpaceFloat();
    updateCreatorTopNav();
    window.scrollTo(0, 0);
    return true;
  } catch (_) {
    return false;
  }
}

window.addEventListener('message', async (event) => {
  const data = event?.data;
  if (!data || !data.url) return;

  // v46: the Service Worker asks this window to resolve a push destination after auth initialization
  // and lets the already-authenticated window handle the route without a reload.
  if (data.type === 'GRAYXON_NOTIFICATION_NAVIGATE_REQUEST') {
    const port = event.ports?.[0];
    let authenticated = !!session?.user?.id;
    let handled = false;
    try {
      // Do not answer the worker while app startup is halfway through restoring Supabase auth.
      if (grayxonInitPromise) {
        try { await Promise.race([grayxonInitPromise, new Promise(resolve => setTimeout(resolve, 7000))]); } catch (_) {}
      }
      if (!authenticated || !session?.user?.id) {
        const { data: sessionData } = await sb.auth.getSession();
        if (sessionData?.session) {
          session = sessionData.session;
          authenticated = true;
        } else {
          authenticated = false;
        }
      }
      if (!authenticated) {
        try {
          const pendingUrl = new URL(data.url, window.location.href);
          if (pendingUrl.searchParams.get('grayxonPush') === '1') {
            saveGrayxonPushIntent(pendingUrl.searchParams.get('page') || 'payments', pendingUrl.searchParams.get('target') || '');
          }
        } catch (_) {}
      }
      if (!authenticated && data.notificationId) saveGrayxonPendingPushNotificationId(data.notificationId);
      if (authenticated && !profile) {
        profile = await getProfile();
        document.body.classList.toggle('grayxon-creator-session', profile?.role === 'creator');
        document.body.classList.toggle('grayxon-manager-session', profile?.role === 'manager');
        updateHeaderAccessUI();
        await loadProfileDetails();
        await loadNotifications();
      }
      if (authenticated && data.notificationId) {
        handled = await openGrayxonNotificationById(data.notificationId);
      }
      // Compatibility fallback for older push payloads that do not include a DB notification ID.
      if (authenticated && !handled) handled = await handleGrayxonDeepLinkUrl(data.url);
    } catch (err) {
      console.warn('No se pudo abrir el destino de la notificación:', err);
    }
    try { port?.postMessage({type:'GRAYXON_NOTIFICATION_NAVIGATE_RESULT', authenticated, handled}); } catch (_) {}
    return;
  }

  // Backwards compatibility with older workers during rollout.
  if (data.type === 'GRAYXON_NOTIFICATION_NAVIGATE') {
    await handleGrayxonDeepLinkUrl(data.url);
  }
});

window.addEventListener('hashchange', async () => {
  const page = window.location.hash.replace(/^#/, '') || 'home';
  const deepLiveMatch = page.match(/^live-training\/([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i);

  // Deep-link LIVE: también debe funcionar cuando Grayxon ya está abierto.
  // No modificamos el flujo normal de live-training; solo interceptamos URLs con UUID.
  if (session && profile?.role === 'creator' && deepLiveMatch) {
    const liveId = deepLiveMatch[1];
    const { data: targetLive } = await sb.from('live_trainings')
      .select('id,title,description,scheduled_at,room_name,status,created_by,instructor_name,created_at,started_at,ended_at')
      .eq('id', liveId)
      .eq('status', 'live')
      .maybeSingle();

    if (targetLive) {
      currentLiveTraining = targetLive;
      pendingLiveTrainingAutoStart = { id: targetLive.id };
      if (current !== 'live-training') {
        current = 'live-training';
        render();
      } else {
        ensureLiveTrainingPage();
      }
      updateCreatorSpaceFloat();
      updateCreatorTopNav();
      window.scrollTo(0, 0);
      return;
    }
  }

  if (page === 'live-training') ensureLiveTrainingPage();
  if (!['home','benefits','auth','space','manager','training','live-training','missions','profile','admin','announcements','payments','events'].includes(page)) return;
  if (current === page) return;
  current = page;
  render();
  updateCreatorSpaceFloat();
  window.scrollTo(0, 0);
});
