let gxAnnouncementRefreshTimer=null,gxAnnouncementRefreshBusy=false;
async function gxCheckAnnouncementUpdates(){
  const feed=$('#gxAnnFeed');if(!feed||!session||current!=='announcements'||gxAnnouncementRefreshBusy)return;
  gxAnnouncementRefreshBusy=true;
  try{
    const {data,error}=await sb.from('announcements').select('id').order('created_at',{ascending:false}).limit(3);
    if(error)throw error;
    const visibleIds=new Set(Array.from(feed.querySelectorAll('[data-ann-card]')).map(node=>node.getAttribute('data-ann-card')));
    const hasNew=(data||[]).some(row=>!visibleIds.has(String(row.id))&&!visibleIds.has(row.id));
    if(hasNew)await gxLoadAnnouncements({silent:true});
  }catch(error){console.warn('Comprobación de nuevos comunicados:',error);}
  finally{gxAnnouncementRefreshBusy=false;}
}
function gxStartAnnouncementAutoRefresh(){
  if(gxAnnouncementRefreshTimer)clearInterval(gxAnnouncementRefreshTimer);
  gxAnnouncementRefreshTimer=setInterval(()=>{
    if(document.hidden||current!=='announcements')return;
    gxCheckAnnouncementUpdates();
  },10000);
}

/* Encuestas y publicaciones: requieren migración de encuestas y adjuntos v1.3. */
function gxRenderPollComposer(teams){
  const mount=$('#gxPollComposerMount'); if(!mount)return;
  const admin=profile?.role==='admin';
  mount.innerHTML=`<details class="gx-ann-composer-details gx-poll-composer-details"><summary class="gx-ann-composer-summary"><span class="gx-ann-compose-icon">☑</span><span><strong>Crear encuesta</strong><small>Consulta opiniones y registra los votos en la plataforma.</small></span><b class="gx-ann-compose-chevron">⌄</b></summary><form id="gxPollComposer" class="gx-ann-composer"><label>Pregunta<input id="gxPollTitle" maxlength="180" required placeholder="Ej. ¿Qué tema quieres para el próximo entrenamiento?"></label><label>Descripción (opcional)<textarea id="gxPollDescription" rows="2" maxlength="2000" placeholder="Agrega contexto para los participantes"></textarea></label><label>Opciones de respuesta<textarea id="gxPollOptions" rows="4" required maxlength="1500" placeholder="Una opción por línea&#10;Entrenamiento&#10;Batallas&#10;Creación de contenido"></textarea><small>Incluye entre 2 y 10 opciones, una por línea.</small></label><div class="gx-ann-targets"><label>Dirigida a<select id="gxPollTarget" ${admin?'':'disabled'}>${admin?'<option value="agency">Toda la agencia</option><option value="managers">Solo managers</option><option value="teams">Equipos específicos</option>':'<option value="teams">Mi equipo</option>'}</select></label><label class="gx-poll-multiple"><span>Tipo de voto</span><select id="gxPollMultiple"><option value="false">Una sola respuesta</option><option value="true">Permitir varias respuestas</option></select></label></div><div id="gxPollTeamChoices" class="gx-ann-team-choices ${admin?'hidden':''}">${(teams||[]).map(t=>`<label><input type="checkbox" name="gxPollTeam" value="${gxAnnouncementEsc(t.id)}" ${!admin?'checked disabled':''}><span>${gxAnnouncementEsc(t.name)}</span></label>`).join('')||'<small>No hay equipos disponibles para asignar.</small>'}</div><label>Fecha de cierre (opcional)<input id="gxPollClosesAt" type="datetime-local"></label><button class="gx-ann-publish" type="submit">Publicar encuesta <span>↗</span></button><div id="gxPollComposerStatus" class="gx-ann-status" aria-live="polite"></div></form></details>`;
  $('#gxPollTarget')?.addEventListener('change',e=>$('#gxPollTeamChoices')?.classList.toggle('hidden',e.target.value!=='teams'));
  $('#gxPollComposer')?.addEventListener('submit',gxCreatePoll);
}
async function gxLoadPolls(){
  const feed=$('#gxPollFeed'); if(!feed||!session)return;
  feed.innerHTML='<div class="gx-ann-empty">Actualizando encuestas…</div>';
  const {data:polls,error}=await sb.from('gx_polls').select('id,author_id,title,description,target_type,allow_multiple,closes_at,created_at,author:profiles!gx_polls_author_id_fkey(full_name,username),gx_poll_options(id,option_text,position),gx_poll_teams(team_id,team:teams(name)),gx_poll_attachments(id,file_name,mime_type,file_size,storage_path)').order('created_at',{ascending:false}).limit(50);
  if(error){feed.innerHTML=`<div class="gx-ann-empty"><strong>No se pudieron cargar las encuestas.</strong><span>${gxAnnouncementEsc(error.message)}<br>Verifica que la migración SQL de encuestas esté aplicada.</span></div>`;return;}
  if(!polls?.length){feed.innerHTML='<div class="gx-ann-empty"><strong>Aún no hay encuestas.</strong><span>Cuando se publique una para tu perfil o equipo, aparecerá aquí.</span></div>';return;}
  const ids=polls.map(p=>p.id);
  const [{data:results,error:voteError},{data:myVotes,error:myVoteError}]=await Promise.all([
    sb.rpc('gx_poll_results',{p_poll_ids:ids}),
    sb.from('gx_poll_votes').select('poll_id,option_id').eq('user_id',session.user.id).in('poll_id',ids)
  ]);
  if(voteError||myVoteError){feed.innerHTML=`<div class="gx-ann-empty"><strong>No se pudieron consultar los votos.</strong><span>${gxAnnouncementEsc((voteError||myVoteError).message)}</span></div>`;return;}
  const votes=(results||[]).map(v=>({poll_id:v.poll_id,option_id:v.option_id,count:Number(v.vote_count)||0})), mine=myVotes||[];
  feed.innerHTML=polls.map(p=>{
    const opts=(p.gx_poll_options||[]).slice().sort((a,b)=>(a.position||0)-(b.position||0));
    const pollVotes=votes.filter(v=>v.poll_id===p.id), myOptions=new Set(mine.filter(v=>v.poll_id===p.id).map(v=>v.option_id));
    const closed=p.closes_at&&new Date(p.closes_at).getTime()<=Date.now(); const canEdit=profile?.role==='admin'||p.author_id===session.user.id;
    const total=pollVotes.reduce((sum,v)=>sum+Number(v.count||0),0), voted=myOptions.size>0;
    const options=opts.map(o=>{const count=Number(pollVotes.find(v=>v.option_id===o.id)?.count||0);const pct=total?Math.round(count/total*100):0;return `<label class="gx-poll-option ${myOptions.has(o.id)?'is-selected':''}"><input type="${p.allow_multiple?'checkbox':'radio'}" name="gx-poll-${p.id}" value="${gxAnnouncementEsc(o.id)}" ${closed||voted?'disabled':''} ${myOptions.has(o.id)?'checked':''}><span class="gx-poll-option-copy"><span>${gxAnnouncementEsc(o.option_text)}</span>${voted||closed?`<span class="gx-poll-result"><i style="width:${pct}%"></i></span>`:''}</span>${voted||closed?`<small>${pct}% · ${count}</small>`:''}</label>`;}).join('');
    const target=p.target_type==='agency'?'Toda la agencia':p.target_type==='managers'?'Solo managers':(p.gx_poll_teams||[]).map(x=>x.team?.name).filter(Boolean).join(', ')||'Equipo';
    return `<article class="gx-ann-card gx-poll-card" data-poll-card="${p.id}"><div class="gx-ann-card-top"><div class="gx-ann-avatar">☑</div><div class="gx-ann-byline"><strong>${gxAnnouncementEsc(p.author?.full_name||p.author?.username||'Grayxon')}</strong><small>${gxAnnouncementEsc(target)} · ${new Date(p.created_at).toLocaleString('es-CO',{dateStyle:'medium',timeStyle:'short'})}${p.closes_at?' · Cierra '+new Date(p.closes_at).toLocaleString('es-CO',{dateStyle:'short',timeStyle:'short'}):''}</small></div>${profile?.role==='admin'?`<button type="button" class="gx-poll-participation-btn" data-poll-participation="${p.id}">Ver participación</button>`:''}${canEdit?`<button type="button" class="gx-poll-edit-trigger" data-edit-poll="${p.id}" title="Editar encuesta">Editar</button><button class="gx-ann-delete" data-delete-poll="${p.id}">Eliminar</button>`:''}</div><h3>${gxAnnouncementEsc(p.title)}</h3>${p.description?`<div class="gx-ann-body">${gxAnnouncementEsc(p.description).replace(/\n/g,'<br>')}</div>`:''}${(p.gx_poll_attachments||[]).length?`<div class="gx-ann-media-grid">${p.gx_poll_attachments.map(f=>`<div class="gx-ann-inline-media" data-poll-inline-path="${gxAnnouncementEsc(f.storage_path)}" data-poll-inline-name="${gxAnnouncementEsc(f.file_name)}" data-poll-inline-mime="${gxAnnouncementEsc(f.mime_type)}"><span class="gx-ann-media-loading">📎 ${gxAnnouncementEsc(f.file_name)}</span></div>`).join('')}</div>`:''}<div class="gx-poll-options">${options}</div><div class="gx-poll-footer"><span>${total} voto${total===1?'':'s'}${p.allow_multiple?' · varias respuestas':''}${closed?' · Encuesta cerrada':voted?' · Ya votaste':''}</span>${!closed&&!voted?`<button class="gx-ann-publish" data-submit-poll="${p.id}">Enviar voto</button>`:''}</div></article>`;
  }).join('');
  feed.querySelectorAll('[data-submit-poll]').forEach(b=>b.addEventListener('click',()=>gxSubmitPoll(b.dataset.submitPoll)));
  feed.querySelectorAll('[data-delete-poll]').forEach(b=>b.addEventListener('click',()=>gxDeletePoll(b.dataset.deletePoll)));
  feed.querySelectorAll('[data-edit-poll]').forEach(b=>b.addEventListener('click',()=>gxEditPoll(b.dataset.editPoll)));
  if(profile?.role==='admin') feed.querySelectorAll('[data-poll-participation]').forEach(b=>b.addEventListener('click',()=>gxShowPollParticipation(b.dataset.pollParticipation)));
  gxTrackVisiblePollCards(feed);
  for(const node of feed.querySelectorAll('[data-poll-inline-path]')){const path=node.dataset.pollInlinePath,mime=node.dataset.pollInlineMime,name=node.dataset.pollInlineName;const {data:d,error:signErr}=await sb.storage.from(GX_POLL_BUCKET).createSignedUrl(path,300,{download:false});if(signErr||!d?.signedUrl){node.innerHTML=`<span class="gx-ann-preview-error">No se pudo cargar ${gxAnnouncementEsc(name)}.</span>`;continue;}if(mime?.startsWith('image/')){node.innerHTML=`<button type="button" class="gx-ann-image-open" aria-label="Ampliar imagen"><img src="${d.signedUrl}" alt="${gxAnnouncementEsc(name)}" loading="lazy" draggable="false"><span>Ampliar imagen ⤢</span></button>`;node.querySelector('button')?.addEventListener('click',()=>gxOpenAnnouncementPreview(d.signedUrl,'image',name));}else if(mime?.startsWith('video/'))node.innerHTML=`<video controls controlsList="nodownload noremoteplayback" disablepictureinpicture playsinline preload="metadata" src="${d.signedUrl}"></video>`;else if(mime?.startsWith('audio/'))node.innerHTML=`<audio controls controlsList="nodownload noremoteplayback" preload="metadata" src="${d.signedUrl}"></audio>`;else if(mime==='application/pdf')node.innerHTML=`<div class="gx-ann-pdf-wrap"><div class="gx-ann-pdf-label">📄 ${gxAnnouncementEsc(name)} · Vista previa</div><iframe title="Vista previa de ${gxAnnouncementEsc(name)}" src="${d.signedUrl}#toolbar=0&navpanes=0&scrollbar=0" loading="lazy"></iframe></div>`;else node.innerHTML=`<span class="gx-ann-preview-error">${gxAnnouncementEsc(name)} · Formato no compatible.</span>`;}
}
// Registra una visualización solo cuando la tarjeta entra en pantalla.
function gxTrackVisiblePollCards(feed){
  if(!session?.user?.id || !feed || !('IntersectionObserver' in window)) return;
  const observer=new IntersectionObserver(entries=>{
    for(const entry of entries){
      if(!entry.isIntersecting || entry.intersectionRatio<0.1) continue;
      const card=entry.target, id=card.dataset.pollCard;
      if(!id || card.dataset.gxViewTracked==='1') continue;
      card.dataset.gxViewTracked='1';
      sb.rpc('gx_poll_record_view',{p_poll_id:id}).then(async({error})=>{
        if(error){console.warn('No se pudo registrar visualización de encuesta:',error.message);card.dataset.gxViewTracked='0';}
        else await gxRefreshAnnouncementUnreadCount();
      });
      observer.unobserve(card);
    }
  },{threshold:[0.1]});
  feed.querySelectorAll('[data-poll-card]').forEach(card=>observer.observe(card));
}
async function gxShowPollParticipation(pollId){
  if(profile?.role!=='admin'){toast('Solo el administrador puede consultar la participación.');return;}
  const {data,error}=await sb.rpc('gx_poll_participation_status',{p_poll_id:pollId});
  if(error){toast(`No se pudo cargar la lista: ${error.message}`);return;}
  const rows=data||[];
  let overlay=document.getElementById('gxPollParticipationOverlay');
  if(!overlay){overlay=document.createElement('div');overlay.id='gxPollParticipationOverlay';overlay.className='gx-poll-participation-overlay';overlay.innerHTML='<section class="gx-poll-participation-dialog" role="dialog" aria-modal="true" aria-labelledby="gxPollParticipationTitle"><button type="button" class="gx-poll-participation-close" aria-label="Cerrar">×</button><h2 id="gxPollParticipationTitle">Participación de la encuesta</h2><p class="gx-poll-participation-note">La visualización se registra cuando la tarjeta entra en pantalla. Los registros empiezan desde que se instala esta función.</p><div class="gx-poll-participation-table-wrap"><table class="gx-poll-participation-table"><thead><tr><th>Persona</th><th>Vio la encuesta</th><th>Votó</th><th>Fecha de voto</th></tr></thead><tbody></tbody></table></div><div class="gx-poll-participation-summary"></div></section>';document.body.appendChild(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('.gx-poll-participation-close'))overlay.classList.remove('is-open');});document.addEventListener('keydown',e=>{if(e.key==='Escape')overlay.classList.remove('is-open');});}
  const tbody=overlay.querySelector('tbody');
  tbody.innerHTML=rows.map(r=>`<tr><td><strong>${gxAnnouncementEsc(r.full_name||r.username||'Sin nombre')}</strong><small>@${gxAnnouncementEsc(r.username||'')}</small></td><td>${r.has_viewed?'Sí':'No registrado'}${r.viewed_at?`<small>${new Date(r.viewed_at).toLocaleString('es-CO')}</small>`:''}</td><td>${r.has_voted?'Sí':'No'}</td><td>${r.voted_at?new Date(r.voted_at).toLocaleString('es-CO'):'—'}</td></tr>`).join('')||'<tr><td colspan="4">No hay destinatarios registrados para esta encuesta.</td></tr>';
  const views=rows.filter(r=>r.has_viewed).length,voters=rows.filter(r=>r.has_voted).length;
  overlay.querySelector('.gx-poll-participation-summary').textContent=`Destinatarios: ${rows.length} · Vieron: ${views} · Votaron: ${voters}`;
  overlay.classList.add('is-open');
}
(function gxPollParticipationStyles(){if(document.getElementById('gx-poll-participation-styles'))return;const style=document.createElement('style');style.id='gx-poll-participation-styles';style.textContent=`
.gx-poll-participation-btn{border:1px solid #475569;background:#171a20;color:#e5e7eb;border-radius:8px;padding:7px 10px;font-size:12px;cursor:pointer;white-space:nowrap}.gx-poll-participation-overlay{display:none;position:fixed;inset:0;z-index:10050;background:rgba(0,0,0,.76);padding:20px;align-items:center;justify-content:center}.gx-poll-participation-overlay.is-open{display:flex}.gx-poll-participation-dialog{position:relative;width:min(900px,100%);max-height:85vh;overflow:auto;background:#101216;color:#f8fafc;border:1px solid #303640;border-radius:16px;padding:24px;box-shadow:0 20px 80px #0009}.gx-poll-participation-close{position:absolute;right:14px;top:10px;border:0;background:transparent;color:#f8fafc;font-size:28px;cursor:pointer}.gx-poll-participation-dialog h2{margin:0 35px 8px 0}.gx-poll-participation-note{font-size:13px;color:#aab3c2;margin:0 0 18px}.gx-poll-participation-table-wrap{overflow:auto}.gx-poll-participation-table{width:100%;border-collapse:collapse;font-size:13px}.gx-poll-participation-table th,.gx-poll-participation-table td{padding:11px 10px;text-align:left;border-bottom:1px solid #2d333d;vertical-align:top}.gx-poll-participation-table th{color:#b9c3d2;font-weight:600}.gx-poll-participation-table small{display:block;color:#9aa4b2;margin-top:4px}.gx-poll-participation-summary{margin-top:16px;font-weight:600;color:#cbd5e1}@media(max-width:600px){.gx-poll-participation-dialog{padding:18px 12px}.gx-poll-participation-table{font-size:12px}.gx-poll-participation-table th,.gx-poll-participation-table td{padding:8px 6px}}
`;document.head.appendChild(style);})();
async function gxCreatePoll(e){
  e.preventDefault();const form=e.currentTarget,status=$('#gxPollComposerStatus'),btn=form.querySelector('button[type="submit"]');
  const title=$('#gxPollTitle')?.value.trim(),description=$('#gxPollDescription')?.value.trim()||null;
  const options=[...new Set(($('#gxPollOptions')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];
  const target=$('#gxPollTarget')?.value||'teams',teams=[...form.querySelectorAll('input[name="gxPollTeam"]:checked')].map(x=>x.value);
  if(!title){status.textContent='Escribe la pregunta.';return;}if(options.length<2||options.length>10){status.textContent='La encuesta debe tener entre 2 y 10 opciones diferentes.';return;}if(target==='teams'&&!teams.length){status.textContent='Selecciona al menos un equipo.';return;}
  const closesRaw=$('#gxPollClosesAt')?.value;const closesAt=closesRaw?new Date(closesRaw).toISOString():null;if(closesAt&&new Date(closesAt)<=new Date()){status.textContent='La fecha de cierre debe estar en el futuro.';return;}
  btn.disabled=true;status.textContent='Publicando encuesta…';
  let createdPollId=null;
  try{
    const {data:p,error}=await sb.from('gx_polls').insert({author_id:session.user.id,title,description,target_type:target,allow_multiple:$('#gxPollMultiple')?.value==='true',closes_at:closesAt}).select('id').single();if(error)throw error;createdPollId=p.id;
    if(target==='teams'){const {error:teamErr}=await sb.from('gx_poll_teams').insert(teams.map(team_id=>({poll_id:p.id,team_id})));if(teamErr)throw teamErr;}
    const {error:optionErr}=await sb.from('gx_poll_options').insert(options.map((option_text,position)=>({poll_id:p.id,option_text,position})));if(optionErr)throw optionErr;
    const {error:notifyError}=await sb.rpc('gx_poll_notify_recipients',{p_poll_id:p.id});if(notifyError)console.warn('Encuesta publicada; notificación pendiente:',notifyError.message);
    form.reset();status.textContent='Encuesta publicada.';await gxLoadPolls();await gxRefreshAnnouncementUnreadCount();toast('Encuesta publicada ✓');
  }catch(err){if(createdPollId){const cleanup=await sb.from('gx_polls').delete().eq('id',createdPollId);if(cleanup.error)console.error('No se pudo revertir encuesta incompleta',cleanup.error);}console.error('Crear encuesta',err);status.textContent=`No se pudo publicar: ${err.message||err}. No se publicará si falla una de sus partes.`;}
  finally{btn.disabled=false;}
}
async function gxPublishUnified(e){
  e.preventDefault();
  const form=e.currentTarget,status=$('#gxComposeStatus'),btn=$('#gxComposePublish');
  const kind=$('#gxComposeKind')?.value||'announcement',title=$('#gxComposeTitle')?.value.trim(),body=$('#gxComposeBody')?.value.trim()||'',label=$('#gxComposeLabel')?.value.trim()||null;
  const target=$('#gxComposeTarget')?.value||'teams',teams=[...form.querySelectorAll('input[name="gxComposeTeam"]:checked')].map(x=>x.value);
  const files=gxUnifiedFiles.slice();
  const options=[...new Set(($('#gxComposeOptions')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];
  const closesRaw=$('#gxComposeClosesAt')?.value;let closesAt=null;
  if(kind==='poll'&&closesRaw){const parsed=new Date(closesRaw);if(Number.isNaN(parsed.getTime())){status.textContent='La fecha de cierre no es válida.';return;}closesAt=parsed.toISOString();if(parsed<=new Date()){status.textContent='La fecha de cierre debe estar en el futuro.';return;}}
  if(!title){status.textContent='Escribe un título.';return;}
  if(kind==='announcement'&&!body&&!files.length){status.textContent='Escribe un mensaje o adjunta al menos un archivo.';return;}
  if(kind==='poll'&&(options.length<2||options.length>10)){status.textContent='La encuesta debe tener entre 2 y 10 opciones diferentes.';return;}
  if(target==='teams'&&!teams.length){status.textContent='Selecciona al menos un equipo.';return;}
  if(files.some(f=>f.size>50*1024*1024)){status.textContent='Cada archivo debe pesar máximo 50 MB.';return;}
  if(files.some(f=>!(f.type.startsWith('image/')||f.type.startsWith('video/')||f.type.startsWith('audio/')||f.type==='application/pdf'))){status.textContent='Adjunta imágenes, video, audio o PDF.';return;}
  btn.disabled=true;status.textContent=kind==='poll'?'Publicando encuesta y archivos…':'Publicando comunicado y archivos…';
  let createdId=null;const uploaded=[];const bucket=kind==='poll'?GX_POLL_BUCKET:GX_ANNOUNCEMENT_BUCKET;
  try{
    if(kind==='announcement'){
      const {data:a,error}=await sb.from('announcements').insert({author_id:session.user.id,title,body,target_type:target,label}).select('id').single();if(error)throw error;createdId=a.id;
      if(target==='teams'){const {error:te}=await sb.from('announcement_teams').insert(teams.map(team_id=>({announcement_id:createdId,team_id})));if(te)throw te;}
      for(const file of files){const safeName=(file.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9._-]+/g,'_').replace(/^_+|_+$/g,'').slice(-100)||'archivo');const path=`${createdId}/${crypto.randomUUID()}-${safeName}`;const {error:up}=await sb.storage.from(bucket).upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(up)throw up;uploaded.push(path);const {error:meta}=await sb.from('announcement_attachments').insert({announcement_id:createdId,uploaded_by:session.user.id,file_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,storage_path:path});if(meta)throw meta;}
      const {error:notifyError}=await sb.rpc('notify_announcement_recipients',{p_announcement_id:createdId});if(notifyError)console.warn('Comunicado publicado; notificación pendiente:',notifyError.message);
    }else{
      const {data:p,error}=await sb.from('gx_polls').insert({author_id:session.user.id,title,description:body||null,target_type:target,allow_multiple:$('#gxComposeMultiple')?.value==='true',closes_at:closesAt,label}).select('id').single();if(error)throw error;createdId=p.id;
      if(target==='teams'){const {error:te}=await sb.from('gx_poll_teams').insert(teams.map(team_id=>({poll_id:createdId,team_id})));if(te)throw te;}
      const {error:oe}=await sb.from('gx_poll_options').insert(options.map((option_text,position)=>({poll_id:createdId,option_text,position})));if(oe)throw oe;
      for(const file of files){const safeName=(file.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9._-]+/g,'_').replace(/^_+|_+$/g,'').slice(-100)||'archivo');const path=`polls/${createdId}/${crypto.randomUUID()}-${safeName}`;const {error:up}=await sb.storage.from(bucket).upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(up)throw up;uploaded.push(path);const {error:meta}=await sb.from('gx_poll_attachments').insert({poll_id:createdId,uploaded_by:session.user.id,file_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,storage_path:path});if(meta)throw meta;}
      const {error:notifyError}=await sb.rpc('gx_poll_notify_recipients',{p_poll_id:createdId});if(notifyError)console.warn('Encuesta publicada; notificación pendiente:',notifyError.message);
    }
    gxUnifiedFiles=[];gxAnnouncementFiles=[];await announcementsTpl();await gxRefreshAnnouncementUnreadCount();toast(kind==='poll'?'Encuesta publicada ✓':'Comunicado publicado ✓');
  }catch(err){console.error('Publicar contenido Grayxon',err);if(uploaded.length)await sb.storage.from(bucket).remove(uploaded);if(createdId){const table=kind==='poll'?'gx_polls':'announcements';const {error:cleanupError}=await sb.from(table).delete().eq('id',createdId);if(cleanupError)console.error('No se pudo revertir publicación incompleta',cleanupError);}status.textContent=`No se pudo completar: ${err.message||err}. Revisa que la migración de adjuntos esté aplicada.`;
  }finally{btn.disabled=false;}
}
async function gxSubmitPoll(id){
  const card=document.querySelector(`[data-poll-card="${CSS.escape(id)}"]`);if(!card)return;
  const selected=[...card.querySelectorAll('.gx-poll-options input:checked')].map(x=>x.value);if(!selected.length){toast('Selecciona al menos una respuesta.');return;}
  const {error}=await sb.from('gx_poll_votes').insert(selected.map(option_id=>({poll_id:id,option_id,user_id:session.user.id})));if(error){toast(`No se pudo registrar el voto: ${error.message}`);return;}toast('Tu voto quedó registrado ✓');await gxLoadPolls();
}
async function gxEditPoll(id){
  const {data:p,error}=await sb.from('gx_polls').select('id,author_id,title,description').eq('id',id).single();
  if(error||!p){toast(`No se pudo abrir la encuesta: ${error?.message||'No encontrada'}`);return;}
  if(profile?.role!=='admin'&&p.author_id!==session?.user?.id){toast('No tienes permiso para editar esta encuesta.');return;}
  const {data:votes,error:voteError}=await sb.from('gx_poll_votes').select('id').eq('poll_id',id).limit(1);
  if(voteError){toast(`No se pudo comprobar si tiene votos: ${voteError.message}`);return;}
  const hasVotes=!!votes?.length;
  const wrap=document.createElement('div');wrap.className='gx-poll-edit-backdrop';
  wrap.innerHTML=`<style>
  .gx-poll-edit-backdrop{position:fixed;inset:0;z-index:10060;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,.76);backdrop-filter:blur(7px);box-sizing:border-box;overflow:auto}
  .gx-poll-edit-dialog{width:min(620px,calc(100vw - 32px));max-height:calc(100dvh - 40px);overflow:auto;margin:auto;padding:26px;border:1px solid #303640;border-radius:20px;background:#101216;color:#f5f6f8;box-shadow:0 24px 80px rgba(0,0,0,.55);box-sizing:border-box}
  .gx-poll-edit-dialog h2{margin:0 0 8px;font-size:24px;line-height:1.2}.gx-poll-edit-help{margin:0 0 22px;color:#aeb5c0;font-size:13px;line-height:1.55}
  .gx-poll-edit-fields{display:grid;gap:16px}.gx-poll-edit-field{display:grid;gap:7px;min-width:0;font-size:13px;font-weight:650;color:#e5e8ed}
  .gx-poll-edit-field input:not([type=file]),.gx-poll-edit-field textarea{display:block;width:100%;min-width:0;box-sizing:border-box;border:1px solid #39414d;border-radius:10px;padding:12px 13px;background:#080a0d;color:#f5f6f8;font:inherit;font-weight:400;line-height:1.45}
  .gx-poll-edit-field textarea{min-height:100px;resize:vertical}.gx-poll-edit-field input[type=file]{display:block;width:100%;box-sizing:border-box;border:1px dashed #4a5360;border-radius:10px;padding:12px;background:#090b0e;color:#dce1e8;font-size:13px}
  .gx-poll-edit-field small{font-weight:400;color:#aeb5c0;line-height:1.5}.gx-poll-edit-field :disabled{opacity:.58;cursor:not-allowed}
  .gx-poll-edit-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.gx-poll-edit-actions button{min-height:42px;padding:10px 16px;border-radius:10px}
  #gxEditPollStatus{margin-top:14px;color:#ffb4c5;font-size:13px;line-height:1.5;overflow-wrap:anywhere}
  @media(max-width:560px){.gx-poll-edit-backdrop{padding:12px}.gx-poll-edit-dialog{width:100%;max-height:calc(100dvh - 24px);padding:20px;border-radius:16px}.gx-poll-edit-dialog h2{font-size:21px}.gx-poll-edit-actions{display:grid;grid-template-columns:1fr}.gx-poll-edit-actions button{width:100%}}
  </style><section class="gx-poll-edit-dialog" role="dialog" aria-modal="true" aria-labelledby="gxEditPollHeading"><h2 id="gxEditPollHeading">Editar encuesta</h2><p class="gx-poll-edit-help">${hasVotes?'Esta encuesta ya tiene votos. Para proteger los resultados, solo podrás reemplazar o volver a adjuntar archivos.':'Puedes actualizar la pregunta, la descripción y los adjuntos. Las opciones de respuesta se conservan.'}</p><div class="gx-poll-edit-fields"><label class="gx-poll-edit-field">Pregunta<input id="gxEditPollTitle" maxlength="180" value="${gxAnnouncementEsc(p.title)}" ${hasVotes?'disabled':''}></label><label class="gx-poll-edit-field">Descripción<textarea id="gxEditPollDescription" rows="4" maxlength="2000" ${hasVotes?'disabled':''}>${gxAnnouncementEsc(p.description||'')}</textarea></label><label class="gx-poll-edit-field">Adjuntar archivo nuevo (opcional)<input id="gxEditPollFile" type="file" accept="image/*,video/*,audio/*,application/pdf"><small>Si el archivo anterior está dañado o falta en Storage, adjunta aquí la versión correcta. Máximo 50 MB.</small></label></div><div id="gxEditPollStatus" aria-live="polite"></div><div class="gx-poll-edit-actions"><button type="button" class="secondary" id="gxEditPollCancel">Cancelar</button><button type="button" class="gx-ann-publish" id="gxEditPollSave">Guardar cambios</button></div></section>`;
  document.body.appendChild(wrap);
  const close=()=>wrap.remove();wrap.querySelector('#gxEditPollCancel').onclick=close;wrap.addEventListener('click',e=>{if(e.target===wrap)close();});
  wrap.querySelector('#gxEditPollSave').onclick=async()=>{
    const btn=wrap.querySelector('#gxEditPollSave'),status=wrap.querySelector('#gxEditPollStatus'),file=wrap.querySelector('#gxEditPollFile').files?.[0];
    const title=wrap.querySelector('#gxEditPollTitle').value.trim(),description=wrap.querySelector('#gxEditPollDescription').value.trim()||null;
    if(!hasVotes&&!title){status.textContent='La pregunta no puede quedar vacía.';return;}
    if(file&&file.size>50*1024*1024){status.textContent='El archivo debe pesar máximo 50 MB.';return;}
    if(file&&!(file.type.startsWith('image/')||file.type.startsWith('video/')||file.type.startsWith('audio/')||file.type==='application/pdf')){status.textContent='Adjunta una imagen, video, audio o PDF.';return;}
    btn.disabled=true;status.textContent='Guardando…';
    try{
      if(!hasVotes){const {error:updateError}=await sb.from('gx_polls').update({title,description}).eq('id',id);if(updateError)throw updateError;}
      if(file){
        const safeName=(file.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9._-]+/g,'_').replace(/^_+|_+$/g,'').slice(-100)||'archivo');
        const path=`polls/${id}/${crypto.randomUUID()}-${safeName}`;
        const {error:uploadError}=await sb.storage.from(GX_POLL_BUCKET).upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(uploadError)throw uploadError;
        const {error:metaError}=await sb.from('gx_poll_attachments').insert({poll_id:id,uploaded_by:session.user.id,file_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,storage_path:path});
        if(metaError){await sb.storage.from(GX_POLL_BUCKET).remove([path]);throw metaError;}
        // New file is safely stored and registered. Remove previous attachment metadata
        // so a broken/missing object does not keep showing the stale error on every reload.
        const {data:oldAttachments,error:oldReadError}=await sb.from('gx_poll_attachments').select('id,storage_path').eq('poll_id',id).neq('storage_path',path);
        if(oldReadError)throw oldReadError;
        if(oldAttachments?.length){
          const {error:oldMetaError}=await sb.from('gx_poll_attachments').delete().eq('poll_id',id).neq('storage_path',path);
          if(oldMetaError)throw oldMetaError;
          const oldPaths=oldAttachments.map(x=>x.storage_path).filter(Boolean);
          if(oldPaths.length){const {error:oldStorageError}=await sb.storage.from(GX_POLL_BUCKET).remove(oldPaths);if(oldStorageError)console.warn('Adjuntos antiguos no eliminados de Storage:',oldStorageError.message);}
        }
      }
      close();toast(file?'Encuesta actualizada y archivo adjuntado ✓':'Encuesta actualizada ✓');await gxLoadPolls();
    }catch(err){status.textContent=`No se pudo guardar: ${err.message||err}`;btn.disabled=false;}
  };
}

async function gxDeletePoll(id){if(!confirm('¿Eliminar esta encuesta y sus votos? Esta acción no se puede deshacer.'))return;const {data:existingVotes,error:voteCheckError}=await sb.from('gx_poll_votes').select('id').eq('poll_id',id).limit(1);if(voteCheckError){toast(`No se pudo verificar la encuesta: ${voteCheckError.message}`);return;}if(existingVotes?.length&&profile?.role!=='admin'){toast('Solo un administrador activo puede eliminar una encuesta que ya tiene votos.');return;}const {data:files}=await sb.from('gx_poll_attachments').select('storage_path').eq('poll_id',id);if(files?.length){const {error:storageError}=await sb.storage.from(GX_POLL_BUCKET).remove(files.map(f=>f.storage_path));if(storageError){toast(`No se pudieron eliminar los adjuntos: ${storageError.message}`);return;}}const {error}=await sb.from('gx_polls').delete().eq('id',id);if(error){toast(`No se pudo eliminar: ${error.message}`);return;}toast('Encuesta eliminada ✓');await gxLoadPolls();await gxRefreshAnnouncementUnreadCount();}
async function gxLoadAnnouncements({silent=false}={}){
  const feed=$('#gxAnnFeed'); if(!feed||!session)return;
  const priorScroll=window.scrollY;
  if(!silent)feed.innerHTML='<div class="gx-ann-empty">Cargando el último comunicado…</div>';
  const {data,error}=await sb.from('announcements').select('id,author_id,title,body,target_type,created_at,author:profiles!announcements_author_id_fkey(full_name,username,role),announcement_teams(team_id,team:teams(name)),announcement_attachments(id,file_name,mime_type,file_size,storage_path)').order('created_at',{ascending:false}).limit(60);
  if(error){feed.innerHTML=`<div class="gx-ann-empty"><strong>No se pudieron cargar los comunicados.</strong><span>${gxAnnouncementEsc(error.message)}<br>Si es la primera instalación, ejecuta primero el SQL incluido en el paquete.</span></div>`;return;}
  const items=data||[]; if(!items.length){feed.innerHTML='<div class="gx-ann-empty"><strong>Aún no hay comunicados.</strong><span>Cuando se publique uno para tu audiencia, aparecerá aquí.</span></div>';await gxRefreshAnnouncementUnreadCount();return;}
  const ids=items.map(x=>x.id);
  const authorIds=[...new Set(items.map(x=>x.author_id).filter(Boolean))];
  const [{data:reads},{data:reactions},{data:mineReads},{data:mineReactions},{data:authorIdentity,error:authorIdentityError}]=await Promise.all([
    profile?.role==='admin'?sb.rpc('grayxon_announcement_read_status',{p_announcement_ids:ids}):Promise.resolve({data:[]}),
    sb.from('announcement_reactions').select('announcement_id,emoji,user_id').in('announcement_id',ids),
    sb.from('announcement_reads').select('announcement_id').eq('user_id',session.user.id).in('announcement_id',ids),
    sb.from('announcement_reactions').select('announcement_id,emoji').eq('user_id',session.user.id).in('announcement_id',ids),
    sb.rpc('gx_announcement_author_profiles',{p_author_ids:authorIds})
  ]);
  if(authorIdentityError) console.warn('No se pudo recuperar la identidad de los autores de comunicados:',authorIdentityError.message);
  const avatarByUser=new Map((authorIdentity||[]).map(x=>[x.author_id,x.avatar_url||'']));
  const authorByUser=new Map((authorIdentity||[]).map(x=>[x.author_id,x]));
  const readSet=new Set((mineReads||[]).map(x=>x.announcement_id)); const myReactions=new Set((mineReactions||[]).map(x=>`${x.announcement_id}:${x.emoji}`));
  feed.innerHTML=items.map(a=>{
    const isCurrentAuthor=a.author_id===session?.user?.id;
    const authorProfile=authorByUser.get(a.author_id);
    const author=(isCurrentAuthor?(profile?.full_name||profile?.username||authorProfile?.full_name||authorProfile?.username):null)||authorProfile?.full_name||authorProfile?.username||a.author?.full_name||a.author?.username||'Usuario';
    const aud=a.target_type==='agency'?'Toda la agencia':a.target_type==='managers'?'Managers':(a.announcement_teams||[]).map(x=>x.team?.name).filter(Boolean).join(', ')||'Equipo';
    const media=(a.announcement_attachments||[]).map(f=>`<div class="gx-ann-inline-media" data-ann-inline-path="${gxAnnouncementEsc(f.storage_path)}" data-ann-inline-name="${gxAnnouncementEsc(f.file_name)}" data-ann-inline-mime="${gxAnnouncementEsc(f.mime_type)}"><span class="gx-ann-media-loading">${f.mime_type?.startsWith('image/')?'🖼️':f.mime_type?.startsWith('video/')?'🎬':f.mime_type?.startsWith('audio/')?'🎧':f.mime_type==='application/pdf'?'📄':'👁️'} ${gxAnnouncementEsc(f.file_name)}</span></div>`).join('');
    const rx=(reactions||[]).filter(r=>r.announcement_id===a.id);const emojiCounts=['👍','❤️','👏','🔥','😂'].map(e=>{const count=rx.filter(r=>r.emoji===e).length;return `<button class="gx-ann-reaction ${myReactions.has(`${a.id}:${e}`)?'is-active':''}" data-ann-react="${a.id}" data-ann-emoji="${e}" aria-label="Reaccionar ${e}">${e}<small>${count||''}</small></button>`}).join('');
    const own=a.author_id===session.user.id; const canDelete=profile?.role==='admin'||(profile?.role==='manager'&&own);
    const readRows=(reads||[]).filter(r=>r.announcement_id===a.id);const readCount=readRows.filter(r=>r.has_read).length;const adminReads=profile?.role==='admin'?`<details class="gx-ann-reads"><summary>Lecturas · ${readCount}/${readRows.length} leyeron</summary><div class="gx-ann-read-list">${readRows.length?readRows.map(r=>`<span>${r.has_read?'✓':'○'} ${gxAnnouncementEsc(r.full_name||r.username||'Usuario')} <small>${r.has_read?`Leído ${new Date(r.read_at).toLocaleString('es-CO')}`:'Pendiente de lectura'}</small></span>`).join(''):'No hay destinatarios activos para este comunicado.'}</div></details>`:'';
    const avatar=avatarByUser.get(a.author_id); const avatarMarkup=avatar?`<img src="${gxAnnouncementEsc(avatar)}" alt="" loading="lazy">`:gxAnnouncementEsc(author.trim().charAt(0).toUpperCase()||'G');
    return `<article class="gx-ann-card" data-ann-card="${a.id}"><div class="gx-ann-card-top"><div class="gx-ann-avatar">${avatarMarkup}</div><div class="gx-ann-byline"><strong>${gxAnnouncementEsc(author)}</strong><small>${new Date(a.created_at).toLocaleString('es-CO',{dateStyle:'medium',timeStyle:'short'})} · ${gxAnnouncementEsc(aud)}</small></div>${canDelete?`<button class="gx-ann-delete" data-ann-delete="${a.id}" title="Eliminar comunicado">Eliminar</button>`:''}</div><h3>${gxAnnouncementEsc(a.title)}</h3><div class="gx-ann-body">${gxAnnouncementEsc(a.body||'').replace(/\n/g,'<br>')}</div>${media?`<div class="gx-ann-media-grid">${media}</div>`:''}<div class="gx-ann-reactions">${emojiCounts}</div>${adminReads}</article>`;
  }).join('');
  // Record the read after rendering. The unique key makes repeat visits safe.
  const unread=ids.filter(id=>!readSet.has(id)); if(!silent&&unread.length) await sb.from('announcement_reads').upsert(unread.map(announcement_id=>({announcement_id,user_id:session.user.id})),{onConflict:'announcement_id,user_id',ignoreDuplicates:true});
  await gxRefreshAnnouncementUnreadCount();
  if(silent)window.scrollTo(0,priorScroll);
  for(const node of feed.querySelectorAll('[data-ann-inline-path]')){const path=node.dataset.annInlinePath;const mime=node.dataset.annInlineMime;const name=node.dataset.annInlineName;const {data:d}=await sb.storage.from(GX_ANNOUNCEMENT_BUCKET).createSignedUrl(path,300,{download:false});if(!d?.signedUrl){node.innerHTML='<span class="gx-ann-preview-error">No se pudo cargar la vista previa.</span>';continue;}if(mime?.startsWith('image/')){node.innerHTML=`<button type="button" class="gx-ann-image-open" aria-label="Ampliar imagen"><img src="${d.signedUrl}" alt="${gxAnnouncementEsc(name)}" loading="lazy" draggable="false" oncontextmenu="return false"><span>Ampliar imagen ⤢</span></button>`;node.querySelector('button')?.addEventListener('click',()=>gxOpenAnnouncementPreview(d.signedUrl,'image',name));}else if(mime?.startsWith('video/'))node.innerHTML=`<video controls controlsList="nodownload noremoteplayback" disablepictureinpicture playsinline preload="metadata" oncontextmenu="return false" src="${d.signedUrl}"></video>`;else if(mime?.startsWith('audio/'))node.innerHTML=`<audio controls controlsList="nodownload noremoteplayback" preload="metadata" oncontextmenu="return false" src="${d.signedUrl}"></audio>`;else if(mime==='application/pdf')node.innerHTML=`<div class="gx-ann-pdf-wrap"><div class="gx-ann-pdf-label">📄 ${gxAnnouncementEsc(name)} · Vista previa</div><iframe title="Vista previa de ${gxAnnouncementEsc(name)}" src="${d.signedUrl}#toolbar=0&navpanes=0&scrollbar=0" loading="lazy" oncontextmenu="return false"></iframe></div>`;else node.innerHTML=`<div class="gx-ann-preview-error">${gxAnnouncementEsc(name)} · Este formato no admite vista previa integrada. Adjunta una imagen, video, audio o PDF para que el contenido se vea aquí sin un botón de descarga.</div>`;}
  feed.querySelectorAll('[data-ann-react]').forEach(b=>b.onclick=()=>gxToggleAnnouncementReaction(b.dataset.annReact,b.dataset.annEmoji));
  feed.querySelectorAll('[data-ann-delete]').forEach(b=>b.onclick=()=>gxDeleteAnnouncement(b.dataset.annDelete));
}
async function gxPublishAnnouncement(e){
  e.preventDefault(); const status=$('#gxAnnComposerStatus');const btn=e.submitter;const title=$('#gxAnnTitle')?.value.trim();const body=$('#gxAnnBody')?.value.trim();const target=$('#gxAnnTarget')?.value||'teams';
  const teamIds=target==='teams'?Array.from(document.querySelectorAll('input[name="gxAnnTeam"]:checked')).map(x=>x.value):[];
  if(!title||(!body&&!gxAnnouncementFiles.length)){status.textContent='Escribe un título y un mensaje o adjunta al menos un archivo.';return;}
  if(target==='teams'&&!teamIds.length){status.textContent='Selecciona al menos un equipo.';return;}
  if(gxAnnouncementFiles.some(f=>f.size>50*1024*1024)){status.textContent='Cada archivo debe pesar máximo 50 MB.';return;}
  if(gxAnnouncementFiles.some(f=>!(f.type.startsWith('image/')||f.type.startsWith('video/')||f.type.startsWith('audio/')||f.type==='application/pdf'))){status.textContent='Para mantener los comunicados en modo visualización, adjunta imágenes, video, audio o PDF.';return;}
  btn.disabled=true;status.textContent='Publicando comunicado…';
  try{
    const {data:a,error}=await sb.from('announcements').insert({author_id:session.user.id,title,body:body||'',target_type:target}).select('id').single();
    if(error)throw error;
    if(teamIds.length){const {error:te}=await sb.from('announcement_teams').insert(teamIds.map(team_id=>({announcement_id:a.id,team_id})));if(te)throw te;}
    for(const file of gxAnnouncementFiles){const safeName=(file.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9._-]+/g,'_').replace(/^_+|_+$/g,'').slice(-100)||'archivo');const path=`${a.id}/${crypto.randomUUID()}-${safeName}`;const {error:up}=await sb.storage.from(GX_ANNOUNCEMENT_BUCKET).upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(up)throw up;const {error:meta}=await sb.from('announcement_attachments').insert({announcement_id:a.id,uploaded_by:session.user.id,file_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,storage_path:path});if(meta)throw meta;}
    const {error:notifyError}=await sb.rpc('notify_announcement_recipients',{p_announcement_id:a.id});if(notifyError)console.warn('Comunicado publicado; notificación pendiente:',notifyError.message);
    gxAnnouncementFiles=[];await announcementsTpl();toast('Comunicado publicado ✓');
  }catch(err){console.error('Publicar comunicado',err);status.textContent=`No se pudo completar: ${err.message||err}. Revisa que la migración SQL esté aplicada y los permisos de almacenamiento configurados.`;}
  finally{if(btn)btn.disabled=false;}
}
async function gxToggleAnnouncementReaction(id,emoji){
  const {data:existing,error:readError}=await sb.from('announcement_reactions').select('announcement_id').eq('announcement_id',id).eq('user_id',session.user.id).eq('emoji',emoji).maybeSingle();if(readError){toast('No se pudo consultar la reacción.');return;}
  const result=existing?await sb.from('announcement_reactions').delete().eq('announcement_id',id).eq('user_id',session.user.id).eq('emoji',emoji):await sb.from('announcement_reactions').insert({announcement_id:id,user_id:session.user.id,emoji});
  if(result.error){toast('No se pudo guardar la reacción.');return;}await gxLoadAnnouncements();
}
async function gxDeleteAnnouncement(id){
  if(!confirm('¿Eliminar este comunicado y sus adjuntos? Esta acción no se puede deshacer.'))return;
  const {data:files}=await sb.from('announcement_attachments').select('storage_path').eq('announcement_id',id);
  if(files?.length)await sb.storage.from(GX_ANNOUNCEMENT_BUCKET).remove(files.map(f=>f.storage_path));
  const {error}=await sb.from('announcements').delete().eq('id',id);if(error){toast(`No se pudo eliminar: ${error.message}`);return;}toast('Comunicado eliminado ✓');await gxLoadAnnouncements();
}
function gxOpenAnnouncementPreview(url,type,name){
  let overlay=document.getElementById('gxAnnPreviewOverlay');if(!overlay){overlay=document.createElement('div');overlay.id='gxAnnPreviewOverlay';overlay.className='gx-ann-preview-overlay';overlay.innerHTML='<button type="button" class="gx-ann-preview-close" aria-label="Cerrar vista previa">✕</button><div class="gx-ann-preview-stage"></div>';document.body.appendChild(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('.gx-ann-preview-close')){overlay.classList.remove('is-open');overlay.querySelector('.gx-ann-preview-stage').replaceChildren();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){overlay.classList.remove('is-open');overlay.querySelector('.gx-ann-preview-stage').replaceChildren();}});}
  const stage=overlay.querySelector('.gx-ann-preview-stage');stage.replaceChildren();const img=document.createElement('img');img.src=url;img.alt=name||'Vista previa';stage.appendChild(img);overlay.classList.add('is-open');
}
