    const selfHandle=self?.tiktok_username||selfProfile?.tiktok_username||'',selfName=selfProfile?.username||selfProfile?.full_name||selfHandle||'Tú',selfUrl=gxEventsTikTokUrl(selfHandle);
    const avatar=(uid,label,href)=>{const src=d.avatarMap?.get(uid)||'',initial=String(label||'?').trim().replace(/^@/,'').charAt(0).toUpperCase()||'?';const face=src?`<img src="${gxEventsEsc(src)}" alt="${gxEventsEsc(label)}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'">` :'';return href?`<a class="gxev-battle-avatar-link" href="${gxEventsEsc(href)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir TikTok de ${gxEventsEsc(label)}">${face}<span class="gxev-battle-avatar-fallback" style="display:${src?'none':'grid'}">${gxEventsEsc(initial)}</span></a>`:`<span class="gxev-battle-avatar-link" aria-label="${gxEventsEsc(label)}">${face}<span class="gxev-battle-avatar-fallback" style="display:${src?'none':'grid'}">${gxEventsEsc(initial)}</span></span>`;};
