async function gxEventsChange(e){if(e.target?.id==='gxevPostFiles'){const label=document.getElementById('gxevPostFilesLabel');if(label){const files=Array.from(e.target.files||[]);label.textContent=files.length?files.length+' archivo(s): '+files.map(f=>f.name).join(', '):'Ningún archivo seleccionado · máximo 100 MB en total';}return;}const t=e.target;if(t.id==='gxevPostAsPoll'){const block=document.getElementById('gxevPollOptions');if(block){block.hidden=!t.checked;block.querySelectorAll('[name="poll_option"]').forEach((input,index)=>input.required=!!t.checked&&index<2);}return;}if(t.id==='gxevParticipantSearch'){const q=String(t.value||'').trim().toLowerCase();const sel=document.querySelector('#gxevAddParticipantForm select[name="user_id"]');if(sel){[...sel.options].forEach(o=>{o.hidden=!!q&&!o.textContent.toLowerCase().includes(q)&&!o.value.toLowerCase().includes(q);});const first=[...sel.options].find(o=>!o.hidden);if(first)sel.value=first.value;}return;}
if(t.id==='gxevParticipantCsv'&&t.files?.[0]){const file=t.files[0],preview=document.querySelector('#gxevParticipantImportPreview'),confirm=document.querySelector('#gxevParticipantImportConfirm');try{const ext=(file.name.split('.').pop()||'').toLowerCase();let parsed;if(ext==='xlsx'||ext==='xls'){const XLSX=await loadXlsxParser();const wb=XLSX.read(await file.arrayBuffer(),{type:'array',raw:false});const ws=wb.Sheets[wb.SheetNames[0]];parsed=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',raw:false}).map(r=>r.map(v=>String(v??'').trim())).filter(r=>r.some(v=>v));}else if(ext==='csv'||ext==='txt'){const text=await file.text();const lines=text.replace(/^\\uFEFF/,'').split(/\\r?\\n/).filter(x=>x.trim());const parseLine=line=>{const out=[];let cur='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&line[i+1]==='"'&&quoted){cur+='"';i++;}else if(ch==='"')quoted=!quoted;else if((ch===','||ch===';'||ch==='\\t')&&!quoted){out.push(cur.trim());cur='';}else cur+=ch;}out.push(cur.trim());return out;};parsed=lines.map(parseLine);}else throw new Error('Selecciona un archivo .xlsx, .xls o .csv.');const head=parsed[0].map(x=>x.toLowerCase().replace(/^@/,'').trim());const idx=head.findIndex(x=>['username','usuario','user','tiktok','tiktok_username','nombre de usuario','nombre','name','full_name','id'].includes(x));const dataRows=(idx>=0?parsed.slice(1):parsed).map(r=>String(r[idx>=0?idx:0]||'').trim()).filter(Boolean);const all=[...(window.gxevParticipantDirectory||[])];const currentIds=new Set(window.gxevParticipantCurrentIds||[]);const norm=x=>String(x||'').trim().replace(/^@/,'').toLowerCase();const found=[],missing=[];for(const raw of dataRows){const key=norm(raw);const u=all.find(p=>norm(p.username)===key||norm(p.full_name)===key||norm(p.id)===key);if(u&&!currentIds.has(u.id)&&!found.some(x=>x.id===u.id))found.push({...u,source:raw});else if(!u)missing.push(raw);}window.gxevParticipantImportMatches=found;window.gxevParticipantImportMissing=missing;preview.innerHTML='<div><b>'+found.length+' cuentas encontradas</b> · '+missing.length+' sin coincidencia · '+dataRows.length+' filas leídas</div>'+(found.length?'<div class="gxev-audience-list" style="margin-top:8px">'+found.map(u=>'<label class="gxev-audience-choice"><input type="checkbox" data-gxev-import-user value="'+gxEventsEsc(u.id)+'" checked><span>@'+gxEventsEsc(u.username||u.full_name||u.id)+' · '+gxEventsEsc(u.role==='manager'?'Manager':'Creador')+'</span></label>').join('')+'</div>':'')+(missing.length?'<details style="margin-top:8px"><summary>Revisar cuentas sin coincidencia</summary><p>'+missing.map(x=>gxEventsEsc(x)).join(', ')+'</p></details>':'');confirm.disabled=!found.length;}catch(err){preview.textContent='No se pudo leer el archivo. Expórtalo desde Excel como CSV UTF-8 e inténtalo otra vez.';confirm.disabled=true;}return;}
if(t.matches('[data-gxev-review-status]'))return;if(t.matches('[data-gxev-match-result]')){t.dataset.changed='1';return;}}
async function gxEventsRespond(response){
  if(!session?.user?.id||!gxEventsSelectedId)return;const buttons=[...document.querySelectorAll('#events [data-gxev-response]')];buttons.forEach(b=>b.disabled=true);
  try{const r=await sb.rpc('gx_events_respond',{p_event_id:gxEventsSelectedId,p_response:response,p_tiktok_username:null});if(r.error)throw new Error(r.error.message);const result=r.data||{};const old=gxEventsMyResponses.find(x=>x.event_id===gxEventsSelectedId);if(old){old.response=response;old.responded_at=new Date().toISOString();old.tiktok_username=result.tiktok_username||old.tiktok_username;}else gxEventsMyResponses.push({event_id:gxEventsSelectedId,user_id:session.user.id,response,tiktok_username:result.tiktok_username||profile?.username||null,responded_at:new Date().toISOString()});const participant=gxEventsMyParticipants.find(x=>x.event_id===gxEventsSelectedId&&x.user_id===session.user.id);if(response==='yes'){if(participant){participant.status='registered';participant.tiktok_username=result.tiktok_username||profile?.username||participant.tiktok_username;}else gxEventsMyParticipants.push({id:result.participant_id||'',event_id:gxEventsSelectedId,user_id:session.user.id,status:'registered',tiktok_username:result.tiktok_username||profile?.username||null,registered_at:new Date().toISOString()});}else if(participant)participant.status='withdrawn';toast(response==='yes'?'¡Inscripción registrada! Tu dashboard ya está listo.':'Respuesta registrada.');await gxEventsReloadDashboard(gxEventsSelectedId,true);}catch(err){toast(err?.message||'No se pudo registrar tu respuesta.');}finally{buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}}
async function gxEventsTogglePostReaction(postId,reaction){if(!session?.user?.id)return toast('Inicia sesión para reaccionar.');if(!['like','heart','fire','clap'].includes(reaction))return;const {data:existing,error}=await sb.from('gx_event_post_reactions').select('id,reaction').eq('post_id',postId).eq('user_id',session.user.id).maybeSingle();if(error)return toast('No se pudo consultar la reacción: '+error.message);let result;if(existing?.reaction===reaction)result=await sb.from('gx_event_post_reactions').delete().eq('id',existing.id);else if(existing)result=await sb.from('gx_event_post_reactions').update({reaction}).eq('id',existing.id);else result=await sb.from('gx_event_post_reactions').insert({event_id:gxEventsSelectedId,post_id:postId,user_id:session.user.id,reaction});if(result.error)return toast('No se pudo guardar la reacción: '+result.error.message);await gxEventsReloadDashboard(gxEventsSelectedId,true);}
async function gxEventsSubmitProgress(missionId){const data=gxEventsDashboardData,m=data?.missions.find(x=>x.id===missionId);if(!m)return;const input=document.querySelector(`[data-gxev-progress-value="${missionId}"]`),value=Number(input?.value);if(!Number.isFinite(value)||value<0)return toast('Ingresa un avance válido.');const currentRow=data.progress.find(p=>p.mission_id===missionId&&p.user_id===session.user.id);if(currentRow?.status==='approved')return toast('Este avance ya fue aprobado; contacta a administración si requiere ajuste.');const payload={event_id:gxEventsSelectedId,mission_id:missionId,user_id:session.user.id,value,evidence_url:null,status:'pending',updated_at:new Date().toISOString()};const r=await sb.from('gx_event_mission_progress').upsert(payload,{onConflict:'mission_id,user_id'});if(r.error)return toast(r.error.message);toast('Avance enviado para revisión ✓');await gxEventsReloadDashboard(gxEventsSelectedId,true);}
async function gxEventsReviewProgress(progressId){if(!gxEventsAdmin())return;const inp=document.querySelector(`[data-gxev-review-value="${progressId}"]`),sel=document.querySelector(`[data-gxev-review-status="${progressId}"]`),val=Number(inp?.value),status=String(sel?.value||'pending');if(!Number.isFinite(val)||val<0)return toast('El valor de avance debe ser válido.');const r=await sb.from('gx_event_mission_progress').update({value:val,status,reviewed_by:session.user.id,reviewed_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',progressId);if(r.error)return toast(r.error.message);toast(status==='approved'?'Avance aprobado; el ranking se actualizará.':status==='rejected'?'Avance devuelto para corrección.':'Avance actualizado.');await gxEventsReloadDashboard(gxEventsSelectedId,true);}
async function gxEventsGenerateRound(phaseId=null){if(!gxEventsAdmin())return;const rounds=gxEventsDashboardData?.rounds||[],n=rounds.length+1;const phase=(gxEventsDashboardData?.phases||[]).find(p=>p.id===phaseId);const title=(gxEventsDashboardData?.event?.battle_format==='single_elimination'?'Ronda ':'Jornada ')+n;const phaseLabel=phase?' para '+phase.title:'';if(!confirm(`¿Generar ${title.toLowerCase()}${phaseLabel} con emparejamientos aleatorios? Los participantes recibirán su aviso.`))return;let result;try{result=await sb.rpc('gx_events_generate_round',{p_event_id:gxEventsSelectedId,p_round_number:n,p_title:title});}catch(err){console.error('Eventos: error inesperado al generar jornada',err);toast('No se pudo generar la jornada: '+(err?.message||String(err)));return;}if(result?.error){console.error('Eventos: RPC gx_events_generate_round falló',result.error);toast('No se pudo generar la jornada: '+(result.error.message||'error desconocido'));return;}const data=result?.data||{};toast(`Jornada creada: ${Number(data.matches)||0} batallas${data.byes?` y ${data.byes} pase(s) libre(s)`:''}.`);await gxEventsReloadDashboard(gxEventsSelectedId,true);}
async function gxEventsSaveMatchSchedule(matchId){if(!gxEventsAdmin())return;const m=gxEventsDashboardData?.matches.find(x=>x.id===matchId);if(!m)return;const input=document.querySelector(`[data-gxev-match-schedule="${matchId}"]`);const raw=String(input?.value||'');if(!raw)return toast('Selecciona la fecha y hora de la batalla.');const round=(gxEventsDashboardData?.rounds||[]).find(r=>r.id===m.round_id),phase=(gxEventsDashboardData?.phases||[]).find(p=>p.id===round?.phase_id);const selected=new Date(raw+'-05:00');if(!Number.isFinite(selected.getTime()))return toast('La fecha y hora no son válidas.');if(phase){const start=new Date(phase.starts_at),end=new Date(phase.ends_at);if(selected<start||selected>end)return toast('El horario debe estar dentro del rango de la fase seleccionada.');}const btn=document.querySelector(`[data-gxev-save-schedule="${matchId}"]`);if(btn)btn.disabled=true;try{const r=await sb.from('gx_event_matches').update({scheduled_at:selected.toISOString(),updated_at:new Date().toISOString()}).eq('id',matchId);if(r.error)return toast('No se pudo guardar el horario: '+r.error.message);const notify=await sb.rpc('gx_events_notify_match_update',{p_match_id:matchId});if(notify.error)console.warn('No se pudo notificar el cambio de horario:',notify.error);toast(notify.error?'Horario guardado, pero falló la notificación.':'Fecha y hora guardadas y notificadas ✓');await gxEventsReloadDashboard(gxEventsSelectedId,true);}finally{if(btn?.isConnected)btn.disabled=false;}}
async function gxEventsSaveMatch(matchId){if(!gxEventsAdmin())return;const m=gxEventsDashboardData?.matches.find(x=>x.id===matchId);if(!m)return;const select=document.querySelector(`[data-gxev-match-result="${matchId}"]`),sa=document.querySelector(`[data-gxev-score-a="${matchId}"]`),sbx=document.querySelector(`[data-gxev-score-b="${matchId}"]`),value=String(select?.value||'');if(!value)return toast('Selecciona ganador o empate.');const winner=value==='a'?m.participant_a_id:value==='b'?m.participant_b_id:null,scoreA=sa?.value===''?null:Number(sa?.value),scoreB=sbx?.value===''?null:Number(sbx?.value);const r=await sb.rpc('gx_events_save_match_result',{p_match_id:matchId,p_winner_participant_id:winner,p_score_a:scoreA,p_score_b:scoreB,p_notes:null});if(r.error)return toast(r.error.message);toast('Resultado guardado y avisos enviados ✓');await gxEventsReloadDashboard(gxEventsSelectedId,true);}

(function gxEventsBindModuleV23(){if(window.__gxEventsModuleV23Bound)return;window.__gxEventsModuleV23Bound=true;document.addEventListener('change',e=>{if(e.target?.id==='gxevParticipantCsv')gxEventsChange(e);},{capture:true});document.addEventListener('click',async e=>{const b=e.target.closest?.('[data-gx-open-events]');if(!b)return;e.preventDefault();if(!session?.user?.id){nav('auth');return;}gxEventsSelectedId=null;gxPendingEventTarget=null;gxPendingEventPostTarget=null;gxPendingEventTab=null;gxEventsExitFullscreen();try{const {data,error}=await sb.rpc('gx_events_latest_unread_post');const latest=!error&&Array.isArray(data)?data[0]:null;if(latest?.event_id&&latest?.post_id){gxPendingEventTarget=latest.event_id;gxPendingEventPostTarget=latest.post_id;gxPendingEventTab='thread';}}catch(err){console.warn('Eventos: abrir publicación pendiente',err);}nav('events');});const refresh=()=>{gxEventsInjectDashboardCard();if(session?.user?.id){gxEventsRefreshUnreadCount().catch(()=>{});gxMissionsRefreshUnreadBadge().catch(()=>{});}};window.addEventListener('focus',refresh);window.addEventListener('pageshow',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});const observer=new MutationObserver(ms=>{let maybe=false;for(const m of ms)for(const n of Array.from(m.addedNodes||[])){if(n.nodeType!==1)continue;if(n.matches?.('.creator-dashboard-grid,.manager-dashboard-grid,.admin-dashboard-grid,#spaceCards')||n.querySelector?.('.creator-dashboard-grid,.manager-dashboard-grid,.admin-dashboard-grid,#spaceCards'))maybe=true;}if(maybe)gxEventsInjectDashboardCard();});observer.observe(document.body,{childList:true,subtree:true});setTimeout(refresh,250);setTimeout(refresh,1200);setInterval(()=>{if(!document.hidden&&session?.user?.id){gxEventsRefreshUnreadCount().catch(()=>{});gxMissionsRefreshUnreadBadge().catch(()=>{});}},30000);})();
